import re
from typing import Tuple

# Token types
NUMBER, PLUS, MINUS, TIMES, DIVIDE, LPAREN, RPAREN, EOF = (
    'NUMBER', 'PLUS', 'MINUS', 'TIMES', 'DIVIDE', 'LPAREN', 'RPAREN', 'EOF'
)

Token = Tuple[str, str]  # (type, value)


class Lexer:
    token_specification = [
        (NUMBER, r'\d+(\.\d*)?|\.\d+'),
        (PLUS, r'\+'),
        (MINUS, r'-'),
        (TIMES, r'\*'),
        (DIVIDE, r'/'),
        (LPAREN, r'\('),
        (RPAREN, r'\)'),
        ('SKIP', r'[ \t]+'),
        ('MISMATCH', r'.'),
    ]

    def __init__(self, text: str):
        self.text = text
        self.tokens = self.tokenize()
        self.pos = 0

    def tokenize(self):
        tok_regex = '|'.join(f'(?P<{name}>{pattern})' for name, pattern in self.token_specification)
        get_token = re.compile(tok_regex).match
        pos = 0
        tokens = []
        while pos < len(self.text):
            m = get_token(self.text, pos)
            if not m:
                raise ValueError(f'Unexpected character {self.text[pos]!r} at position {pos}')
            typ = m.lastgroup
            if typ == 'SKIP':
                pass
            elif typ == 'MISMATCH':
                raise ValueError(f'Unexpected character {m.group()} at position {pos}')
            else:
                tokens.append((typ, m.group()))
            pos = m.end()
        tokens.append((EOF, ''))
        return tokens

    def peek(self) -> Token:
        return self.tokens[self.pos]

    def advance(self):
        self.pos += 1

    def expect(self, token_type: str):
        typ, val = self.peek()
        if typ != token_type:
            raise ValueError(f'Expected {token_type} but got {typ}')
        self.advance()
        return val


class Parser:
    def __init__(self, lexer: Lexer):
        self.lexer = lexer

    def parse(self) -> float:
        if self.lexer.peek()[0] == EOF:
            raise ValueError('Empty expression')
        result = self.expr()
        if self.lexer.peek()[0] != EOF:
            raise ValueError('Unexpected token after end of expression')
        return result

    def expr(self) -> float:
        """expr : term ((PLUS|MINUS) term)*"""
        result = self.term()
        while True:
            tok_type, _ = self.lexer.peek()
            if tok_type == PLUS:
                self.lexer.advance()
                result += self.term()
            elif tok_type == MINUS:
                self.lexer.advance()
                result -= self.term()
            else:
                break
        return result

    def term(self) -> float:
        """term : factor ((TIMES|DIVIDE) factor)*"""
        result = self.factor()
        while True:
            tok_type, _ = self.lexer.peek()
            if tok_type == TIMES:
                self.lexer.advance()
                result *= self.factor()
            elif tok_type == DIVIDE:
                self.lexer.advance()
                denom = self.factor()
                if denom == 0:
                    raise ZeroDivisionError('division by zero')
                result /= denom
            else:
                break
        return result

    def factor(self) -> float:
        """factor : (MINUS)* primary"""
        neg = False
        while self.lexer.peek()[0] == MINUS:
            self.lexer.advance()
            neg = not neg
        value = self.primary()
        return -value if neg else value

    def primary(self) -> float:
        """primary : NUMBER | LPAREN expr RPAREN"""
        tok_type, val = self.lexer.peek()
        if tok_type == NUMBER:
            self.lexer.advance()
            return float(val)
        if tok_type == LPAREN:
            self.lexer.advance()
            val = self.expr()
            if self.lexer.peek()[0] != RPAREN:
                raise ValueError('Unbalanced parentheses')
            self.lexer.advance()
            return val
        raise ValueError(f'Unexpected token {tok_type}')


def evaluate(expr: str) -> float:
    """
    Evaluate an arithmetic expression containing integers, decimals,
    +, -, *, /, parentheses and unary minus.

    Raises:
        ValueError: for malformed input.
        ZeroDivisionError: when division by zero occurs.
    """
    lexer = Lexer(expr)
    parser = Parser(lexer)
    return parser.parse()
